//! Languages. The Czech site has no prefix; the German (Austrian) one lives
//! under `/at`. The language comes from the address only, so a shared link
//! opens in the language it was shared in.

use serde::{Deserialize, Serialize};
use std::borrow::Cow;

// TODO: replace with the locale type generated by `codon` from locales/*.yml.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Locale {
    #[default]
    Cs,
    De,
}

impl Locale {
    pub fn as_str(self) -> &'static str {
        match self {
            Locale::Cs => "cs",
            Locale::De => "de",
        }
    }

    /// The URL prefix of the language, if it has one.
    pub fn url_prefix(self) -> Option<&'static str> {
        match self {
            Locale::Cs => None,
            Locale::De => Some("at"),
        }
    }

    /// The language a site path is in.
    pub fn of_path(path: &str) -> Locale {
        match path.strip_prefix("/at") {
            Some(rest) if rest.is_empty() || rest.starts_with(['/', '?', '#']) => Locale::De,
            _ => Locale::Cs,
        }
    }

    /// `path` (Czech, unprefixed) in this language: "/kontakt#cenik" → "/at/kontakt#cenik".
    pub fn path(self, path: &str) -> String {
        let base = strip_prefix(path);
        match self.url_prefix() {
            None => base.into_owned(),
            Some(prefix) => {
                let rest = if base == "/" || base.starts_with("/?") || base.starts_with("/#") { &base[1..] } else { &base };
                format!("/{prefix}{rest}")
            }
        }
    }

    /// The other language (the header's language switch).
    pub fn other(self) -> Locale {
        match self {
            Locale::Cs => Locale::De,
            Locale::De => Locale::Cs,
        }
    }

    /// "de-AT" for hreflang.
    pub fn hreflang(self) -> &'static str {
        match self {
            Locale::Cs => "cs",
            Locale::De => "de-AT",
        }
    }

    pub fn currency(self) -> &'static str {
        match self {
            Locale::Cs => "CZK",
            Locale::De => "EUR",
        }
    }
}

/// The same path without a language prefix: "/at/kontakt" → "/kontakt",
/// "/at" → "/", "/at?x=1" → "/?x=1", "/atlas" stays.
pub fn strip_prefix(path: &str) -> Cow<'_, str> {
    match path.strip_prefix("/at") {
        Some("") => Cow::Borrowed("/"),
        Some(rest) if rest.starts_with('/') => Cow::Borrowed(rest),
        Some(rest) if rest.starts_with(['?', '#']) => Cow::Owned(format!("/{rest}")),
        _ => Cow::Borrowed(path),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn paths() {
        assert_eq!(Locale::De.path("/kontakt#cenik"), "/at/kontakt#cenik");
        assert_eq!(Locale::De.path("/"), "/at");
        assert_eq!(Locale::De.path("/?category=rezivo"), "/at?category=rezivo");
        assert_eq!(Locale::De.path("/at/eshop"), "/at/eshop");
        assert_eq!(Locale::Cs.path("/at/eshop/tramy"), "/eshop/tramy");
        assert_eq!(Locale::Cs.path("/at"), "/");
        assert_eq!(Locale::Cs.path("/atlas"), "/atlas");
        assert_eq!(Locale::of_path("/at/kontakt"), Locale::De);
        assert_eq!(Locale::of_path("/at"), Locale::De);
        assert_eq!(Locale::of_path("/atlas"), Locale::Cs);
        assert_eq!(strip_prefix("/at?x=1"), "/?x=1");
    }
}
